import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import ReviewSection from './ReviewSection';

const MovieList = () => {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    fetchMovies();
  }, []);

  const fetchMovies = async () => {
    try {
      const response = await fetch('http://localhost:8080/api/movies');
      const data = await response.json();

      // Add poster URLs to movies
      const moviePosters = {
        'Avengers: Endgame': 'https://images.unsplash.com/photo-1604537466158-719cb1974170?w=400',
        'Spider-Man: No Way Home': 'https://images.unsplash.com/photo-1635805717198-91d6b3e5eeeb?w=400',
        'The Batman': 'https://images.unsplash.com/photo-1578919334674-aed05f518b0c?w=400',
        'Dune': 'https://images.unsplash.com/photo-1594736797933-d0acc240191b5?w=400',
        'Top Gun: Maverick': 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=400',
        'Black Panther: Wakanda Forever': 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba8?w=400',
        'Avatar: The Way of Water': 'https://images.unsplash.com/photo-1533938393693-1f0d6be1c8ea?w=400',
        'Jurassic World: Dominion': 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400'
      };

      const moviesWithPosters = data.map(movie => ({
        ...movie,
        posterUrl: moviePosters[movie.title] || null
      }));
      setMovies(moviesWithPosters);
    } catch (error) {
      console.error('Error fetching movies:', error);
    } finally {
      setLoading(false);
    }
  };

  const genres = [...new Set(movies.map(movie => movie.genre))];

  const filteredMovies = movies.filter(movie => {
    const matchesSearch = movie.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesGenre = !selectedGenre || movie.genre === selectedGenre;
    return matchesSearch && matchesGenre;
  });

  const handleBookMovie = (movie) => {
    navigate(`/booking/${movie.movieId}`);
  };

  const handleViewReviews = (movie) => {
    setSelectedMovie(movie);
    setShowReviewModal(true);
  };

  const handleCloseReviewModal = () => {
    setShowReviewModal(false);
    setSelectedMovie(null);
  };

  const handleReviewSubmit = (reviewData) => {
    console.log('New review submitted:', reviewData);
    // Optionally refresh movies or update local state
    handleCloseReviewModal();
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading movies...</p>
      </div>
    );
  }

  return (
    <div>
      {/* Hero Section */}
      <div className="hero">
        <div className="hero-content">
          <h1 className="hero-title">
            🎬 CINEMA EXPERIENCE
          </h1>
          <p className="hero-subtitle">
            Book tickets for the latest blockbuster movies
          </p>
        </div>

        <div className="search-bar">
          <div className="search-container">
            <input
              type="text"
              placeholder="Search movies..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="form-input search-input"
            />

            <select
              value={selectedGenre}
              onChange={(e) => setSelectedGenre(e.target.value)}
              className="form-input filter-select"
            >
              <option value="">All Genres</option>
              {genres.map(genre => (
                <option key={genre} value={genre}>{genre}</option>
              ))}
            </select>
          </div>
        </div>

        {filteredMovies.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '4rem' }}>
            <h2 style={{ color: 'var(--text-secondary)' }}>
              No movies found
            </h2>
            <p style={{ color: 'var(--text-secondary)', marginTop: '1rem' }}>
              Try adjusting your search or filter criteria
            </p>
          </div>
        ) : (
          <div className="movie-grid">
            {filteredMovies.map(movie => (
              <div key={movie.movieId} className="movie-card">
                <div className="movie-poster glitch-poster" onClick={() => handleBookMovie(movie)}>
                  {movie.posterUrl ? (
                    <img src={movie.posterUrl} alt={movie.title} />
                  ) : (
                    <span style={{ fontSize: '4rem' }}>🎬</span>
                  )}
                  <div className="movie-badge">
                    NEW
                  </div>
                </div>
                <div className="movie-info">
                  <h3 className="movie-title">{movie.title}</h3>
                  <p className="movie-description">{movie.description}</p>
                  <div className="movie-meta">
                    <span className="movie-genre">{movie.genre}</span>
                    <span className="movie-rating">⭐ {movie.rating}</span>
                    <span className="movie-price">₹{movie.price}</span>
                  </div>
                  <div className="movie-actions">
                    <button 
                      className="btn btn-primary"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleBookMovie(movie);
                      }}
                    >
                      🎫 Book Tickets
                    </button>
                    <button 
                      className="btn btn-secondary"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleViewReviews(movie);
                      }}
                    >
                      💬 Reviews
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Review Modal */}
      {showReviewModal && selectedMovie && (
        <div className="modal-overlay" onClick={handleCloseReviewModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{selectedMovie.title} - Reviews</h2>
              <button className="close-btn" onClick={handleCloseReviewModal}>❌</button>
            </div>
            <div className="modal-body">
              <ReviewSection 
                movieId={selectedMovie.movieId}
                onReviewSubmit={handleReviewSubmit}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MovieList;
